def choice(identifier, level, section, concept, prompt, options, correct, hints, explanation, steps, takeaway):
    return {
        "id": identifier, "type": "choice", "level": level, "section": section,
        "concept": concept, "prompt": prompt,
        "choices": [{"id": key, "label": label} for key, label in options],
        "answer": {"choiceId": correct, "display": dict(options)[correct]},
        "hints": hints, "explanation": explanation, "workedSteps": steps, "takeaway": takeaway,
    }


def numeric(identifier, level, section, concept, prompt, value, display, hints, explanation, steps, takeaway, *, unit=None, tolerance=0.0001):
    answer = {"numericValue": float(value), "tolerance": tolerance, "display": display}
    if unit:
        answer["unit"] = unit
    return {
        "id": identifier, "type": "numeric", "level": level, "section": section,
        "concept": concept, "prompt": prompt, "answer": answer,
        "hints": hints, "explanation": explanation, "workedSteps": steps, "takeaway": takeaway,
    }


def chapter(identifier, number, title, description, focus, challenges):
    return {"id": identifier, "number": number, "title": title, "description": description, "focus": focus, "challenges": challenges}


