def validate_catalog(catalog):
    if catalog["schemaVersion"] != "quant-practice.v1" or len(catalog["chapters"]) != 7:
        raise ValueError("Expected versioned seven-chapter catalog")
    identifiers = set()
    chapter_ids = set()
    levels = {"foundation", "application", "challenge"}
    for index, ch in enumerate(catalog["chapters"], 1):
        if ch["id"] in chapter_ids or ch["number"] != index:
            raise ValueError("Duplicate or unordered chapter")
        chapter_ids.add(ch["id"])
        if len(ch["challenges"]) < 8:
            raise ValueError("Every chapter needs at least eight challenges")
        for q in ch["challenges"]:
            if q["id"] in identifiers:
                raise ValueError("Duplicate challenge identifier")
            identifiers.add(q["id"])
            if q["level"] not in levels or len(q["hints"]) != 2 or len(q["workedSteps"]) < 2:
                raise ValueError("Incomplete teaching support")
            text_fields = [q[key] for key in ("id", "section", "concept", "prompt", "explanation", "takeaway")]
            text_fields += q["hints"] + q["workedSteps"] + [q["answer"]["display"]]
            if any(not isinstance(text, str) or not text.strip() for text in text_fields):
                raise ValueError("Missing exercise text")
            if q["type"] == "numeric":
                a = q["answer"]
                if not math.isfinite(a["numericValue"]) or not math.isfinite(a["tolerance"]) or a["tolerance"] <= 0:
                    raise ValueError("Invalid numeric answer")
                if a.get("unit") == "probability" and not 0 <= a["numericValue"] <= 1:
                    raise ValueError("Probability outside [0, 1]")
            elif q["type"] == "choice":
                keys = [option["id"] for option in q["choices"]]
                if len(keys) != len(set(keys)) or q["answer"]["choiceId"] not in keys:
                    raise ValueError("Invalid choice answer")
            else:
                raise ValueError("Unsupported challenge type")
    return catalog


def export_catalog(path=ROOT / "content.json"):
    catalog = validate_catalog(build_catalog())
    path.write_text(json.dumps(catalog, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return catalog


if __name__ == "__main__":
    result = export_catalog()
    print(f"Exported {len(result['chapters'])} chapters and {sum(len(c['challenges']) for c in result['chapters'])} original challenges")
